static Job buf[CAP]; static size_t head, tail, len; static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full = PTHREAD_COND_INITIALIZER, not_empty = PTHREAD_COND_INITIALIZER;
void q_push(Job j) {
    pthread_mutex_lock(&m);
    while (len == CAP) pthread_cond_wait(&not_full, &m);  /* paced */
    buf[tail = (tail + 1) % CAP] = j; len++;
    pthread_cond_broadcast(&not_empty); pthread_mutex_unlock(&m); }
Job q_pop(void) {
    pthread_mutex_lock(&m);
    while (len == 0) pthread_cond_wait(&not_empty, &m);   /* waits */
    Job j = buf[head = (head + 1) % CAP]; len--;
    pthread_cond_signal(&not_full); pthread_mutex_unlock(&m); return j; }

